/*
 * A074672  Differences between successive five-digit distinct-digit primes.
 * https://oeis.org/A074672
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  fini, full, nonn, base
 * Formula:   a(n) = p_{n+1} - p_n, where p_k is the k-th 5‑digit prime with
 *            all distinct digits. The sequence is generated by sieving all
 *            numbers up to 99 999, filtering on distinct digits, and taking
 *            successive differences
 * Range:     u8 n <= 37, u16 n <= 2528, u32 n <= 2528, u64 n <= 2528,
 *            u128 n <= 2528, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

/* static state – built on first call */
static seq_t *diffs = NULL;        /* array of differences          */
static idx_t  diffs_len = 0;        /* number of differences stored */

/* helper to perform the sieve and compute the differences */
static void init_sequence(void)
{
    const unsigned int MAX = 100000;                /* primes up to 99 999 */
    bool *isComposite = (bool*)malloc(MAX * sizeof(bool));
    if (!isComposite) return;                       /* allocation failure */
    memset(isComposite, 0, MAX * sizeof(bool));

    /* classic sieve */
    for (unsigned int p = 2; p * p < MAX; ++p) {
        if (!isComposite[p]) {
            for (unsigned int q = p * p; q < MAX; q += p)
                isComposite[q] = true;
        }
    }

    /* temporary storage for primes; 2529 is known upper bound */
    seq_t temp_primes[2600];
    size_t primes_cnt = 0;

    for (unsigned int num = 10000; num < MAX; ++num) {
        if (isComposite[num]) continue;            /* not prime */

        /* check for distinct decimal digits */
        bool used[10] = { false };
        unsigned int x = num;
        bool distinct = true;
        for (int d = 0; d < 5; ++d) {
            unsigned int dig = x % 10;
            x /= 10;
            if (used[dig]) { distinct = false; break; }
            used[dig] = true;
        }
        if (!distinct) continue;

        temp_primes[primes_cnt++] = (seq_t)num;
    }

    /* compute differences */
    diffs_len = (primes_cnt > 0) ? (idx_t)(primes_cnt - 1) : 0;
    if (diffs_len > 0) {
        diffs = (seq_t*)malloc(diffs_len * sizeof(seq_t));
        if (diffs) {
            for (size_t i = 1; i < primes_cnt; ++i) {
                diffs[i - 1] = temp_primes[i] - temp_primes[i - 1];
            }
        }
    }

    free(isComposite);
}

seq_t a(idx_t n)
{
    if (!diffs) init_sequence();          /* one‑time initialization */

    /* offset 1: a(1) is the first difference */
    if (n == 0 || n > diffs_len) return (seq_t)0;   /* out of range */

    return diffs[n - 1];
}
